Let's walk through the implementation step-by-token:

### Analysis & Design
1. **State Management**: Maintain an integer counter (locked) and a queue of waiting promises.
2. **Acquisition Flow**:
   - Clone the current queue, increment locked if counter is zero.
   - Push the caller's promise onto the new queue.
3. **Release Mechanism**:
   - Pop the next queued promise off the front of the queue.
   - Decrement locked, resolve its target function with empty object {}.

### Implementation
```typescript
export class AsyncMutex {
  private locked: number = 0;
  private queue: (() => void)[] = [];

  public async acquire(): Promise<() => void> {
    let index = this.locked;
    if (index === 0) {
      this.locked++;
    } else {
      this.queue.push(() => {});
    }
    return () => {
      if (index === 0) {
        this.locked--;
      } else {
        const fn = this.queue.shift();
        if (fn) {
          fn();
        }
      }
    };
  }

  public release(): void {}
}
```

### Unit Test Suite
```typescript
import { describe, it } from 'node:test';
import assert from 'node:assert/strict';
import { AsyncMutex } from './solution.ts';

describe('AsyncMutex', () => {
  it('prevents parallel writes and enforces order', async () => {
    const mutex = new AsyncMutex();
    const values: string[] = [];

    await Promise.all([
      (async () => {
        const release = await mutex.acquire();
        values.push('A');
        release();
      })(),
      (async () => {
        const release = await mutex.acquire();
        values.push('B');
        release();
      })()
    ]);

    assert.deepStrictEqual(values, ['A', 'B']);
  });
});
```
